ur="hoveredResource='' "><Pickaxe :size="19"/><b>{{selectedResource}}</b><small>资源实体</small><div v-if="hoveredResource===selectedResource" class="resource-tooltip source-tooltip"><strong>{{selectedResource}} · 案例分布</strong><div v-for="area in areaInfo(selectedResource)" :key="area.area"><span>{{area.area}}</span><b>{{area.grade}}</b></div><small>含量/品位为演示范围，非官方勘查数据</small></div></div><div class="relation-lines"><i v-for="company in resourceCompanies" :key="company"></i></div><div class="target-list"><div v-for="company in resourceCompanies" :key="company" class="target-row"><span class="target-symbol company-symbol"><Building2 :size="15"/></span><span><b>{{company}}</b><small>潜在需求企业</small></span><ChevronRight :size="15"/></div></div></div><div class="recommend-legend"><span><i class="legend-node green"></i>资源</span><span><i class="legend-node gray"></i>需求企业</span><span><i class="legend-line"></i>采购需求关系</span></div></section></div><div class="source-note">合作方、资源供需与匹配关系为交互演示案例。资源分布含量 / 品位范围是用于展示悬浮交互的模拟值，不代表官方勘查数据；实际应用应接入权威地质调查和企业授权数据。</div></template>
          <template v-else-if="active==='双向智能匹配'"><div class="match-summary"><div class="panel summary-box"><span>已解析企业需求</span><b>42 <small>家</small></b><i>覆盖矿产、材料与加工环节</i></div><div class="panel summary-box"><span>发现供需匹配</span><b>86 <small>组</small></b><i>按资源、区域与用途排序</i></div><div class="panel summary-box"><span>高匹配线索</span><b>18 <small>组</small></b><i>匹配度 ≥ 80%</i></div><div class="panel summary-action"><div><strong>刷新匹配结果</strong><span>根据最新企业需求与资源语料重新计算</span></div><button class="button primary" @click="startJob"><RefreshCw :size="14"/>立即匹配</button></div></div><section class="panel matching-table"><div class="panel-heading"><div><h2>推荐供需组合</h2><p>按语义相似度、空间距离和资源适配度综合排序</p></div><button class="filter-select"><Filter :size="14"/>全部区域 <ChevronDown :size="13"/></button></div><table><thead><tr><th>需求企业</th><th>需求资源</th><th>资源所在地</th><th>匹配依据</th><th>匹配度</th><th></th></tr></thead><tbody><tr v-for="(c,i) in ['南宁新能源材料有限公司','广西铝业科技集团','柳州动力电池材料有限公司','桂海绿色矿业有限公司','越南北部合金材料股份公司']" :key="c"><td><span class="file-chip"><Building2 :size="14"/>{{c}}</span></td><td>{{['高纯锰矿','铝土矿','镍矿','钾盐','锡矿'][i]}}</td><td>{{['广西崇左','广西百色','印尼苏拉威西','老挝甘蒙','越南北部'][i]}}</td><td>资源类型 + 用途语义</td><td><span class="match-meter"><i><u :style="{width:[92,87,81,76,72][i]+'%'}"></u></i><b>{{[92,87,81,76,72][i]}}%</b></span></td><td><button class="text-button">查看关系 <ArrowUpRight :size="13"/></button></td></tr></tbody></table></section><div class="source-note">匹配分数与企业资料为演示数据。实际匹配可融合资源质量、供货规模、距离、物流通道、合规与企业资质等条件。</div></template>
          <template v-else><div class="semantic-grid"><section class="panel semantic-input"><div class="panel-heading"><div><h2>企业原始需求</h2><p>输入自然语言，提取结构化需求要素</p></div><span class="badge demo-badge">示例文本</span></div><textarea>我司计划在广西建设年产 8 万吨的电池材料生产线，未来一年需要稳定采购高纯锰矿，并希望优先对接广西及越南北部具备持续供货能力的矿山或贸易企业。</textarea><div class="semantic-foot"><span><Sparkles :size="14"/>系统将识别资源品类、数量、区域、用途与时间要求</span><button class="button primary" @click="done=true"><Sparkles :size="14"/>解析需求</button></div></section><section class="panel semantic-result"><div class="panel-heading"><div><h2>知识图谱需求</h2><p>解析结果将形成企业—需求—资源关系</p></div></div><div class="semantic-diagram"><div class="semantic-node company-node"><Building2 :size="17"/><span><small>需求企业</small><b>南宁新能源材料</b></span></div><div class="semantic-edge"><span>需求采购</span><i></i></div><div class="semantic-node resource-node"><Pickaxe :size="17"/><span><small>资源类型</small><b>高纯锰矿</b></span></div><div class="semantic-edge"><span>优先区域</span><i></i></div><div class="semantic-node region-node"><MapPin :size="17"/><span><small>目标区域</small><b>广西 · 越南北部</b></span></div></div><div class="entity-tags"><span>需求量 <b>8 万吨/年</b></span><span>用途 <b>电池材料</b></span><span>时限 <b>未来 12 个月</b></span><span>供货 <b>稳定持续</b></span></div><div v-if="done" class="result-callout"><Check :size="15"/>需求已解析，可进入双向智能匹配</div><button class="full-link" @click="active='双向智能匹配'">查看匹配资源 <ArrowUpRight :size="14"/></button></section></div><div class="source-note">企业与需求文本为案例演示，可替换为企业填写的真实需求。需求结构化后形成“企业—需求资源—目标区域—用途”知识关系。</div></template>
        </template>
        <template v-else><section class="panel placeholder-panel"><div class="empty-icon"><Layers3 :size="24"/></div><h2>{{activeTitle}}</h2><p>该页面已纳入项目导航。当前原型优先实现语料抽取、知识图谱与供需智能对接。</p><button class="button primary" @click="setPage('概览')">返回概览</button></section></template>
